CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK (role IN ('Admin','Sales','Warehouse','Accounts')),is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customers (id SERIAL PRIMARY KEY,name TEXT NOT NULL,mobile TEXT NOT NULL,email TEXT,business_name TEXT,gst_number TEXT,customer_type TEXT CHECK (customer_type IN ('Retail','Wholesale','Distributor')),address TEXT,status TEXT DEFAULT 'Lead' CHECK (status IN ('Lead','Active','Inactive')),follow_up_date DATE,notes TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,name TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,category TEXT,unit_price NUMERIC(10,2) NOT NULL DEFAULT 0,current_stock INTEGER NOT NULL DEFAULT 0,min_stock_alert INTEGER NOT NULL DEFAULT 0,warehouse_location TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS stock_movements (id SERIAL PRIMARY KEY,product_id INTEGER REFERENCES products(id),quantity_changed INTEGER NOT NULL,movement_type TEXT NOT NULL CHECK (movement_type IN ('IN','OUT')),reason TEXT,created_by INTEGER REFERENCES users(id),created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS challans (id SERIAL PRIMARY KEY,challan_number TEXT UNIQUE NOT NULL,customer_id INTEGER REFERENCES customers(id),total_quantity INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Confirmed','Cancelled')),created_by INTEGER REFERENCES users(id),created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS challan_items (id SERIAL PRIMARY KEY,challan_id INTEGER REFERENCES challans(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id),product_name_snapshot TEXT NOT NULL,unit_price_snapshot NUMERIC(10,2) NOT NULL,quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id SERIAL PRIMARY KEY,invoice_number TEXT UNIQUE NOT NULL,challan_id INTEGER REFERENCES challans(id),subtotal NUMERIC(10,2) NOT NULL,tax_percent NUMERIC(5,2) NOT NULL DEFAULT 0,total NUMERIC(10,2) NOT NULL,created_by INTEGER REFERENCES users(id),created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customer_followups (id SERIAL PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,note TEXT NOT NULL,created_by INTEGER REFERENCES users(id),created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,details TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_customers_search ON customers(name,business_name,mobile,email);
CREATE INDEX IF NOT EXISTS idx_products_search ON products(name,sku,category);
CREATE INDEX IF NOT EXISTS idx_stock_product_date ON stock_movements(product_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_date ON audit_logs(created_at DESC);
